if (!gdjs.__yAxisPhysicsCharacter3D) {
    gdjs.__yAxisPhysicsCharacter3D = (function() {
        const epsilon = Math.pow(2, -20);
        const toBool = (value) => value === true || value === 'true' || value === 'yes' || value === 1 || value === '1';
        const toNumber = (value, fallback) => {
            const number = Number(value);
            return Number.isFinite(number) ? number : fallback;
        };
        const getNumber = (behavior, name, fallback) => {
            const getter = behavior && behavior['_get' + name];
            return typeof getter === 'function' ? toNumber(getter.call(behavior), fallback) : fallback;
        };
        const getString = (behavior, name, fallback) => {
            const getter = behavior && behavior['_get' + name];
            return typeof getter === 'function' ? String(getter.call(behavior)) : fallback;
        };
        const getBoolean = (behavior, name, fallback) => {
            const getter = behavior && behavior['_get' + name];
            return typeof getter === 'function' ? toBool(getter.call(behavior)) : fallback;
        };
        const getUpY = () => -1;
        const getPhysicsBehavior = (behavior, object) => {
            if (!object || typeof object.getBehavior !== 'function') return null;
            const configuredName = 'Physics3D';
            if (configuredName) {
                try {
                    const configured = object.getBehavior(configuredName);
                    if (configured) return configured;
                } catch (error) {}
            }
            try {
                return object.getBehavior('Physics3D');
            } catch (error) {
                return null;
            }
        };
        const angleDifference = (a, b) => gdjs.evtTools && gdjs.evtTools.common && gdjs.evtTools.common.angleDifference
            ? gdjs.evtTools.common.angleDifference(a, b)
            : ((a - b + 180) % 360 + 360) % 360 - 180;
        const setVec3 = (vec3, x, y, z) => {
            vec3.Set(x, y, z);
            return vec3;
        };

        class CharactersManager {
            constructor() {
                this.characterVsCharacterCollision = new Jolt.CharacterVsCharacterCollisionSimple();
            }
            static getManager(instanceContainer) {
                if (!instanceContainer.__yAxisPhysicsCharacter3DCharactersManager) {
                    instanceContainer.__yAxisPhysicsCharacter3DCharactersManager = new CharactersManager();
                }
                return instanceContainer.__yAxisPhysicsCharacter3DCharactersManager;
            }
            addCharacter(character) {
                this.characterVsCharacterCollision.Add(character);
                character.SetCharacterVsCharacterCollision(this.characterVsCharacterCollision);
            }
            removeCharacter(character) {
                this.characterVsCharacterCollision.Remove(character);
            }
            destroy() {
                Jolt.destroy(this.characterVsCharacterCollision);
            }
        }

        class CharacterCollisionChecker {
            constructor(characterBehavior) {
                this.characterBehavior = characterBehavior;
                this._currentContacts = [];
                this._previousContacts = [];
            }
            clearContacts() {
                this._previousContacts.length = 0;
                this._currentContacts.length = 0;
            }
            updateContacts() {
                const swap = this._previousContacts;
                this._previousContacts = this._currentContacts;
                this._currentContacts = swap;
                this._currentContacts.length = 0;
                const character = this.characterBehavior.character;
                const sharedData = this.characterBehavior._sharedData;
                if (!character || !sharedData) return;
                const contacts = character.GetActiveContacts();
                for (let index = 0; index < contacts.size(); index++) {
                    const contact = contacts.at(index);
                    const bodyLockInterface = sharedData.physicsSystem.GetBodyLockInterface();
                    const body = bodyLockInterface.TryGetBody(contact.mBodyB);
                    let physicsBehavior = body && body.gdjsAssociatedBehavior;
                    if (!physicsBehavior && contact.mCharacterB) {
                        const otherBody = bodyLockInterface.TryGetBody(contact.mCharacterB.GetInnerBodyID());
                        physicsBehavior = otherBody && otherBody.gdjsAssociatedBehavior;
                    }
                    if (physicsBehavior) this._currentContacts.push(physicsBehavior);
                }
            }
            isColliding(object) {
                return !!this.characterBehavior.character && this._currentContacts.some((behavior) => behavior.owner === object);
            }
            hasCollisionStartedWith(object) {
                return !!this.characterBehavior.character &&
                    this._currentContacts.some((behavior) => behavior.owner === object) &&
                    !this._previousContacts.some((behavior) => behavior.owner === object);
            }
            hasCollisionStoppedWith(object) {
                return !!this.characterBehavior.character &&
                    !this._currentContacts.some((behavior) => behavior.owner === object) &&
                    this._previousContacts.some((behavior) => behavior.owner === object);
            }
        }

        class CharacterBodyUpdater {
            constructor(characterBehavior) {
                this.characterBehavior = characterBehavior;
            }
            createAndAddBody() {
                const physics3D = this.characterBehavior.getPhysics3D();
                if (!physics3D) return null;
                const behavior = physics3D.behavior;
                const characterBehavior = this.characterBehavior;
                const owner3D = characterBehavior.owner3D;
                const sharedData = characterBehavior._sharedData;
                const shape = behavior.createShapeWithoutMassCenterOffset();
                const settings = new Jolt.CharacterVirtualSettings();
                settings.mInnerBodyLayer = characterBehavior._canBePushed ? 0 : behavior.getBodyLayer();
                settings.mInnerBodyShape = shape;
                settings.mMass = shape.GetMassProperties().get_mMass();
                settings.mMaxSlopeAngle = gdjs.toRad(characterBehavior._slopeMaxAngle);
                settings.mShape = shape;
                if (characterBehavior._upVector) Jolt.destroy(characterBehavior._upVector);
                characterBehavior._upVector = new Jolt.Vec3();
                characterBehavior._upVector.Set(0, characterBehavior.getUpY(), 0);
                settings.mUp = characterBehavior._upVector;
                settings.mBackFaceMode = Jolt.EBackFaceMode_CollideWithBackFaces;
                const width = owner3D.getWidth() * sharedData.worldInvScale;
                const height = owner3D.getHeight() * sharedData.worldInvScale;
                const depth = owner3D.getDepth() * sharedData.worldInvScale;
                const capsuleHalfLength = height / 2;
                const capsuleRadius = Math.sqrt(width * depth) / 2;
                settings.mSupportingVolume = new Jolt.Plane(
                    characterBehavior._upVector,
                    capsuleHalfLength - capsuleRadius * (1 - Math.cos(gdjs.toRad(Math.min(characterBehavior._slopeMaxAngle + 20, 70))))
                );
                const character = new Jolt.CharacterVirtual(
                    settings,
                    characterBehavior._getPhysicsPosition(sharedData.getRVec3(0, 0, 0)),
                    characterBehavior._getPhysicsRotation(sharedData.getQuat(0, 0, 0, 1)),
                    sharedData.physicsSystem
                );
                Jolt.destroy(settings);
                const body = sharedData.physicsSystem.GetBodyLockInterface().TryGetBody(character.GetInnerBodyID());
                if (characterBehavior.character) {
                    if (characterBehavior._canBePushed) {
                        characterBehavior.charactersManager.removeCharacter(characterBehavior.character);
                        Jolt.destroy(characterBehavior.character.GetListener());
                    }
                    Jolt.destroy(characterBehavior.character);
                }
                characterBehavior.character = character;
                if (characterBehavior._canBePushed) {
                    characterBehavior.charactersManager.addCharacter(character);
                    const listener = new Jolt.CharacterContactListenerJS();
                    listener.OnAdjustBodyVelocity = () => {};
                    listener.OnContactValidate = () => true;
                    listener.OnCharacterContactValidate = (characterPtr, otherCharacterPtr) => {
                        const character = Jolt.wrapPointer(characterPtr, Jolt.CharacterVirtual);
                        const otherCharacter = Jolt.wrapPointer(otherCharacterPtr, Jolt.CharacterVirtual);
                        const body = sharedData.physicsSystem.GetBodyLockInterface().TryGetBody(character.GetInnerBodyID());
                        const otherBody = sharedData.physicsSystem.GetBodyLockInterface().TryGetBody(otherCharacter.GetInnerBodyID());
                        const physicsBehavior = body && body.gdjsAssociatedBehavior;
                        const otherPhysicsBehavior = otherBody && otherBody.gdjsAssociatedBehavior;
                        if (!physicsBehavior || !otherPhysicsBehavior) return true;
                        return physicsBehavior.canCollideAgainst(otherPhysicsBehavior);
                    };
                    listener.OnContactAdded = () => {};
                    listener.OnContactPersisted = () => {};
                    listener.OnContactRemoved = () => {};
                    listener.OnCharacterContactAdded = () => {};
                    listener.OnCharacterContactPersisted = () => {};
                    listener.OnCharacterContactRemoved = () => {};
                    listener.OnContactSolve = () => {};
                    listener.OnCharacterContactSolve = () => {};
                    character.SetListener(listener);
                }
                return body;
            }
            updateObjectFromBody() {
                const character = this.characterBehavior.character;
                if (!character) return;
                this.characterBehavior._moveObjectToPhysicsPosition(character.GetPosition());
                this.characterBehavior._moveObjectToPhysicsRotation(character.GetRotation());
            }
            updateBodyFromObject() {
                const physics3D = this.characterBehavior.getPhysics3D();
                if (!physics3D) return;
                const behavior = physics3D.behavior;
                const character = this.characterBehavior.character;
                const owner3D = this.characterBehavior.owner3D;
                const sharedData = this.characterBehavior._sharedData;
                if (!character) return;
                if (behavior._objectOldX !== owner3D.getX() || behavior._objectOldY !== owner3D.getY() || behavior._objectOldZ !== owner3D.getZ()) {
                    this.updateCharacterPosition();
                }
                if (behavior._objectOldRotationX !== owner3D.getRotationX() || behavior._objectOldRotationY !== owner3D.getRotationY() || behavior._objectOldRotationZ !== owner3D.getAngle()) {
                    character.SetRotation(this.characterBehavior._getPhysicsRotation(sharedData.getQuat(0, 0, 0, 1)));
                }
            }
            updateCharacterPosition() {
                const character = this.characterBehavior.character;
                const sharedData = this.characterBehavior._sharedData;
                if (!character) return;
                character.SetPosition(this.characterBehavior._getPhysicsPosition(sharedData.getRVec3(0, 0, 0)));
            }
            recreateShape() {
                const physics3D = this.characterBehavior.getPhysics3D();
                if (!physics3D) return;
                const behavior = physics3D.behavior;
                const character = this.characterBehavior.character;
                const sharedData = this.characterBehavior._sharedData;
                if (!character) return;
                const shape = behavior.createShapeWithoutMassCenterOffset();
                const isShapeValid = character.SetShape(
                    shape,
                    Number.MAX_VALUE,
                    physics3D.broadPhaseLayerFilter,
                    physics3D.objectLayerFilter,
                    physics3D.bodyFilter,
                    physics3D.shapeFilter,
                    sharedData.jolt.GetTempAllocator()
                );
                if (!isShapeValid) return;
                character.SetInnerBodyShape(shape);
                character.SetMass(shape.GetMassProperties().get_mMass());
                this.updateCharacterPosition();
            }
            destroyBody() {
                this.characterBehavior._destroyBody();
            }
        }

        class YAxisPhysicsCharacterController {
            constructor(eventsBehavior, owner, runtimeScene) {
                this.eventsBehavior = eventsBehavior;
                this.owner = owner;
                this.owner3D = owner;
                this.runtimeScene = runtimeScene;
                this._physics3DBehaviorName = getString(eventsBehavior, 'Physics3D', 'Physics3D');
                this._physics3D = null;
                this._isHookedToPhysicsStep = false;
                this.character = null;
                this._sharedData = null;
                this._upVector = null;
                this._destroyedDuringFrameLogic = false;
                this._lastError = '';
                this._slopeMaxAngle = 0;
                this._slopeClimbingFactor = 1;
                this._slopeClimbingMinNormalY = Math.cos(Math.PI / 4);
                this._forwardAngle = this.readObjectForwardAngle();
                this._hasPressedForwardKey = false;
                this._hasPressedBackwardKey = false;
                this._hasPressedRightKey = false;
                this._hasPressedLeftKey = false;
                this._hasPressedJumpKey = false;
                this._hasUsedStick = false;
                this._stickAngle = 0;
                this._stickForce = 0;
                this._currentForwardSpeed = 0;
                this._currentSidewaysSpeed = 0;
                this._currentFallSpeed = 0;
                this._canJump = false;
                this._currentJumpSpeed = 0;
                this._timeSinceCurrentJumpStart = 0;
                this._jumpKeyHeldSinceJumpStart = false;
                this._hasReallyMoved = false;
                this._oldPhysicsPosition = [0, 0];
                this._wasLeftKeyPressed = false;
                this._wasRightKeyPressed = false;
                this._wasForwardKeyPressed = false;
                this._wasBackwardKeyPressed = false;
                this._wasJumpKeyPressed = false;
                this._wasStickUsed = false;
                this._clearInputsBetweenFrames = true;
                this._steppedThisFrame = false;
                this._stepCount = 0;
                this._lastStepSource = 'none';
                this._lastConsoleStatus = '';
                this._lastConsoleStepLog = 0;
                this.collisionChecker = new CharacterCollisionChecker(this);
                this.charactersManager = CharactersManager.getManager(runtimeScene);
                this.refreshFromProperties();
            }
            activated() {
                return !this.eventsBehavior.activated || this.eventsBehavior.activated();
            }
            getUpY() {
                return getUpY(this.eventsBehavior);
            }
            refreshFromProperties() {
                this._deactivateConsoleLogging = getBoolean(this.eventsBehavior, 'DeactivateConsoleLogging', false);
                this._physics3DBehaviorName = getString(this.eventsBehavior, 'Physics3D', this._physics3DBehaviorName || 'Physics3D');
                this.setSlopeMaxAngle(getNumber(this.eventsBehavior, 'SlopeMaxAngle', 50));
                this._forwardAcceleration = Math.abs(getNumber(this.eventsBehavior, 'ForwardAcceleration', 1200));
                this._forwardDeceleration = Math.abs(getNumber(this.eventsBehavior, 'ForwardDeceleration', 1200));
                this._forwardSpeedMax = Math.abs(getNumber(this.eventsBehavior, 'ForwardSpeedMax', 600));
                this._sidewaysAcceleration = Math.abs(getNumber(this.eventsBehavior, 'SidewaysAcceleration', 800));
                this._sidewaysDeceleration = Math.abs(getNumber(this.eventsBehavior, 'SidewaysDeceleration', 800));
                this._sidewaysSpeedMax = Math.abs(getNumber(this.eventsBehavior, 'SidewaysSpeedMax', 400));
                this._gravity = Math.abs(getNumber(this.eventsBehavior, 'Gravity', 1000));
                this._maxFallingSpeed = Math.abs(getNumber(this.eventsBehavior, 'FallingSpeedMax', 700));
                this._jumpSustainTime = getNumber(this.eventsBehavior, 'JumpSustainTime', 0.2);
                this._jumpHeight = Math.abs(getNumber(this.eventsBehavior, 'JumpHeight', 200));
                this._jumpSpeed = this.getJumpSpeedToReach(this._jumpHeight);
                this._shouldBindObjectAndForwardAngle = getBoolean(this.eventsBehavior, 'ShouldBindObjectAndForwardAngle', true);
                this._stairHeightMax = getNumber(this.eventsBehavior, 'StairHeightMax', 20);
                this._canBePushed = getBoolean(this.eventsBehavior, 'CanBePushed', true);
            }
            getVec3(x, y, z) {
                return setVec3(this._sharedData._tempVec3, x, y, z);
            }
            _debugLog(message, level, force) {
                if (this._deactivateConsoleLogging) return;
                if (typeof console === 'undefined') return;
                level = level || 'log';
                force = !!force;
                const text = '[YAxisPhysicsCharacter3D] ' + message;
                if (!force && text === this._lastConsoleStatus) return;
                this._lastConsoleStatus = text;
                const method = console[level] || console.log;
                if (typeof method === 'function') method.call(console, text);
            }
            _setLastError(message) {
                this._lastError = message;
                this._debugLog(message, 'warn');
            }
            _debugStepStatus(oldX, oldY, oldZ) {
                if (this._stepCount !== 1 && this._stepCount - this._lastConsoleStepLog < 60) return;
                this._lastConsoleStepLog = this._stepCount;
                const position = this.character ? this.character.GetPosition() : null;
                const message = 'step=' + this._stepCount +
                    '; source=' + this._lastStepSource +
                    '; character=' + (!!this.character) +
                    '; body=' + (!!(this._physics3D && this._physics3D.behavior && this._physics3D.behavior._body)) +
                    '; onFloor=' + this.isOnFloor() +
                    '; canJump=' + this._canJump +
                    '; jump=' + this._currentJumpSpeed.toFixed(2) +
                    '; fall=' + this._currentFallSpeed.toFixed(2) +
                    '; forward=' + this._currentForwardSpeed.toFixed(2) +
                    '; side=' + this._currentSidewaysSpeed.toFixed(2) +
                    '; inputs=' + [
                        this._hasPressedForwardKey ? 'F' : '',
                        this._hasPressedBackwardKey ? 'B' : '',
                        this._hasPressedLeftKey ? 'L' : '',
                        this._hasPressedRightKey ? 'R' : '',
                        this._hasPressedJumpKey ? 'J' : '',
                        this._hasUsedStick ? 'S' : ''
                    ].join('') +
                    '; moved=' + this._hasReallyMoved +
                    '; pos=' + (position ? (position.GetX().toFixed(3) + ',' + position.GetY().toFixed(3) + ',' + position.GetZ().toFixed(3)) : 'none') +
                    '; old=' + oldX.toFixed(3) + ',' + oldY.toFixed(3) + ',' + oldZ.toFixed(3);
                this._debugLog(message, 'log', true);
            }
            getPhysics3D() {
                if (this._destroyedDuringFrameLogic) return null;
                if (this._physics3D) return this._physics3D;
                if (!this.activated()) return null;
                const behavior = getPhysicsBehavior(this.eventsBehavior, this.owner);
                if (!behavior) {
                    this._setLastError('Add a Physics3D behavior to the same object and select it in the Y-axis character behavior settings.');
                    return null;
                }
                if (behavior.activated && !behavior.activated()) {
                    this._setLastError('The selected Physics3D behavior is deactivated.');
                    return null;
                }
                if (behavior._shape === 'Mesh') behavior._shape = 'Capsule';
                if (behavior._shape !== 'Box') behavior.shapeOrientation = 'Y';
                const sharedData = behavior._sharedData;
                if (!sharedData) {
                    this._setLastError('The selected Physics3D behavior has no shared physics data yet.');
                    return null;
