                this._sharedData = sharedData;
                this._lastError = '';
                const jolt = sharedData.jolt;
                this._physics3D = {
                    behavior,
                    extendedUpdateSettings: new Jolt.ExtendedUpdateSettings(),
                    broadPhaseLayerFilter: new Jolt.DefaultBroadPhaseLayerFilter(jolt.GetObjectVsBroadPhaseLayerFilter(), gdjs.Physics3DSharedData.dynamicBroadPhaseLayerIndex),
                    objectLayerFilter: new Jolt.DefaultObjectLayerFilter(jolt.GetObjectLayerPairFilter(), behavior.getBodyLayer()),
                    bodyFilter: new Jolt.BodyFilter(),
                    shapeFilter: new Jolt.ShapeFilter(),
