                this.setStairHeightMax(this._stairHeightMax);
                this._isHookedToPhysicsStep = false;
                const previousBodyData = {
                    linearVelocityX: 0,
                    linearVelocityY: 0,
                    linearVelocityZ: 0,
                    angularVelocityX: 0,
                    angularVelocityY: 0,
                    angularVelocityZ: 0,
