                if (behavior._body) {
                    const linearVelocity = behavior._body.GetLinearVelocity();
                    previousBodyData.linearVelocityX = linearVelocity.GetX();
                    previousBodyData.linearVelocityY = linearVelocity.GetY();
                    previousBodyData.linearVelocityZ = linearVelocity.GetZ();
                    const angularVelocity = behavior._body.GetAngularVelocity();
                    previousBodyData.angularVelocityX = angularVelocity.GetX();
                    previousBodyData.angularVelocityY = angularVelocity.GetY();
                    previousBodyData.angularVelocityZ = angularVelocity.GetZ();
                    behavior.bodyUpdater.destroyBody();
                }
                behavior.bodyUpdater = new CharacterBodyUpdater(this);
                behavior.collisionChecker = this.collisionChecker;
                behavior.recreateBody(previousBodyData);
                if (!this.character || !behavior._body) {
                    this._setLastError('Unable to create the Jolt CharacterVirtual body. Try a Box or Capsule Physics3D shape with non-zero size.');
                } else {
                    this._debugLog('created character body; shape=' + behavior._shape + '; bodyLayer=' + behavior.getBodyLayer() + '; hooked=' + this._isHookedToPhysicsStep, 'log', true);
                }
                this._forwardAngle = this.readObjectForwardAngle();
                return this._physics3D;
            }
            readObjectForwardAngle() {
                const source = 'Object Y rotation';
                if (source === 'Object Y rotation' && this.owner3D && typeof this.owner3D.getRotationY === 'function') return this.owner3D.getRotationY();
                return this.owner3D && typeof this.owner3D.getAngle === 'function' ? this.owner3D.getAngle() : this._forwardAngle || 0;
            }
            writeObjectForwardAngle(angle) {
                const source = 'Object Y rotation';
                if (source === 'Object Y rotation' && this.owner3D && typeof this.owner3D.setRotationY === 'function') this.owner3D.setRotationY(angle);
                else if (this.owner3D && typeof this.owner3D.setAngle === 'function') this.owner3D.setAngle(angle);
            }
            _getPhysicsPosition(result) {
                const physics3D = this.getPhysics3D();
                if (!physics3D) {
                    result.Set(0, 0, 0);
                    return result;
                }
                result.Set(
                    this.owner3D.getCenterXInScene() * this._sharedData.worldInvScale,
                    this.owner3D.getCenterYInScene() * this._sharedData.worldInvScale,
                    this.owner3D.getZ() * this._sharedData.worldInvScale
                );
                return result;
            }
            _getPhysicsRotation(result) {
                const rotation = result.sEulerAngles(this.getVec3(0, gdjs.toRad(this.readObjectForwardAngle()), 0));
