                Jolt.destroy(rotation);
                return result;
            }
            _moveObjectToPhysicsPosition(physicsPosition) {
                if (!this.getPhysics3D()) return;
                this.owner3D.setCenterXInScene(physicsPosition.GetX() * this._sharedData.worldScale);
                this.owner3D.setCenterYInScene(physicsPosition.GetY() * this._sharedData.worldScale);
                this.owner3D.setZ(physicsPosition.GetZ() * this._sharedData.worldScale);
            }
            _moveObjectToPhysicsRotation(physicsRotation) {
                const threeObject = this.owner3D.get3DRendererObject && this.owner3D.get3DRendererObject();
                if (!threeObject || typeof THREE === 'undefined') return;
                threeObject.quaternion.x = physicsRotation.GetX();
                threeObject.quaternion.y = physicsRotation.GetY();
                threeObject.quaternion.z = physicsRotation.GetZ();
                threeObject.quaternion.w = physicsRotation.GetW();
