                    this.charactersManager.removeCharacter(this.character);
                    Jolt.destroy(this.character.GetListener());
                }
                this.collisionChecker.clearContacts();
                Jolt.destroy(this.character);
                this.character = null;
                if (this._physics3D) {
                    const behavior = this._physics3D.behavior;
                    behavior.resetToDefaultBodyUpdater();
                    behavior.resetToDefaultCollisionChecker();
                    behavior._body = null;
                    Jolt.destroy(this._physics3D.extendedUpdateSettings);
                    Jolt.destroy(this._physics3D.broadPhaseLayerFilter);
                    Jolt.destroy(this._physics3D.objectLayerFilter);
                    Jolt.destroy(this._physics3D.bodyFilter);
                    Jolt.destroy(this._physics3D.shapeFilter);
                    if (this._upVector) {
                        Jolt.destroy(this._upVector);
                        this._upVector = null;
                    }
                    this._isHookedToPhysicsStep = false;
                    this._physics3D = null;
                }
            }
            onDestroy() {
                this._destroyedDuringFrameLogic = true;
