                this._destroyBody();
            }
            _stepFromPostEvents() {
                this._steppedThisFrame = false;
                this._lastStepSource = 'post-events-callback';
                const physics3D = this.getPhysics3D();
                if (!physics3D) return;
                const timeManager = this.runtimeScene && this.runtimeScene.getTimeManager ? this.runtimeScene.getTimeManager() : null;
                const timeDelta = timeManager ? timeManager.getElapsedTime() / 1000 : 1 / 60;
                this.doBeforePhysicsStep(timeDelta);
                if (physics3D.behavior && typeof physics3D.behavior.updateObjectFromBody === 'function') {
                    physics3D.behavior.updateObjectFromBody();
                }
