                this.getPhysics3D();
            }
            doStepPostEvents() {
                this.getPhysics3D();
            }
            doBeforePhysicsStep(timeDelta) {
                if (this._steppedThisFrame) return;
                this._steppedThisFrame = true;
                if (this._lastStepSource === 'none') this._lastStepSource = 'post-events-callback';
                if (!this.activated()) return;
                const physics3D = this.getPhysics3D();
                if (!physics3D) return;
                if (!this.character) {
                    this._setLastError('The Y-axis character body has not been created yet. Check the selected Physics3D behavior and object shape.');
                    return;
